def stroke_extend(grid, wall, source_labels, target_map):
 h,w=grid.shape
 wallset=set(map(tuple,np.argwhere(grid==wall)))
 # seeds target for line pixels with 8-neighbor source components
 seedmap={}
 for r,c in wallset:
  cols=[]
  for rr in range(max(0,r-1),min(h,r+2)):
   for cc in range(max(0,c-1),min(w,c+2)):
    if (rr,cc)!=(r,c) and source_labels[rr,cc] in target_map:
     cols.append(target_map[source_labels[rr,cc]])
  if cols: seedmap[(r,c)]=Counter(cols).most_common(1)[0][0]
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 neigh={p:[(p[0]+dr,p[1]+dc) for dr,dc in dirs if (p[0]+dr,p[1]+dc) in wallset] for p in wallset}
 nodes={p for p in wallset if len(neigh[p])!=2}
 visited=set(); assignments={}
 # handle isolated loops with no nodes
 for start in list(nodes):
  for nxt in neigh[start]:
   e=tuple(sorted((start,nxt)))
   if e in visited: continue
   path=[start,nxt]; visited.add(e); prev=start;cur=nxt
   while cur not in nodes:
    opts=[q for q in neigh[cur] if q!=prev]
    if not opts: break
    q=opts[0]; ee=tuple(sorted((cur,q)))
    if ee in visited: break
    visited.add(ee);path.append(q);prev,cur=cur,q
   # label edge if any seeds
   cols=[seedmap[p] for p in path if p in seedmap]
   if cols:
    # majority seed color
    lab=Counter(cols).most_common(1)[0][0]
    for p in path: assignments[p]=lab
 # nodes with seed labels also assigned, choose local majority
 for p,col in seedmap.items(): assignments[p]=col
 out=grid.copy()
 for p,col in assignments.items(): out[p]=col
 return out,assignments,seedmap,neigh,nodes
