  cols=[]
  for rr in range(max(0,r-1),min(h,r+2)):
   for cc in range(max(0,c-1),min(w,c+2)):
    if (rr,cc)!=(r,c) and source_labels[rr,cc] in target_map: cols.append(target_map[source_labels[rr,cc]])
  if cols: seedmap[(r,c)]=Counter(cols).most_common(1)[0][0]
 neigh={p:[(p[0]+dr,p[1]+dc) for dr,dc in dirs if (p[0]+dr,p[1]+dc) in wallset] for p in wallset}
 nodes={p for p in wallset if len(neigh[p])!=2};visited=set(); assignments={}; paths=[]
 for start in list(nodes):
  for nxt in neigh[start]:
   e=tuple(sorted((start,nxt)))
   if e in visited: continue
   path=[start,nxt];visited.add(e);prev=start;cur=nxt
   while cur not in nodes:
    opts=[q for q in neigh[cur] if q!=prev]
    if not opts:break
    q=opts[0];ee=tuple(sorted((cur,q)))
    if ee in visited:break
    visited.add(ee);path.append(q);prev,cur=cur,q
